# -*- coding: utf-8 -*-
# Нелин 11, часть 2 (§ 17–§ 22): скан учебника + самостоятельный пересчёт (check_nel2.py).
QG = "в условии была искажена запись (сверено со сканом учебника Нелин 11): "
KB = "ключ неверен (пересчитано вручную, сверено с учебником Нелин 11): "
SRC = "самостоятельная проверка + скан учебника Нелин 11, 25.09"
P = {}
def E(t, why, **kw):
    P[t] = {"why": why, "src": SRC}; P[t].update(kw)
OLD = lambda v, n: [(v, "прежний (неверный) ключ: " + n)]
E("G11_TB_§20_2", KB + "замена 2^x − 2^{−x} = u даёт u² + u − 2 = 0, откуда 2^x = (1 + √5)/2 или 2^x = √2 − 1 (решение учебника, § 20, задача 2); x = 0 не корень: 1 + 1 + 1 − 1 − 4 ≠ 0",
  k=r"$x = \log_{2}\dfrac{1+\sqrt{5}}{2}$; $x = \log_{2}(\sqrt{2}-1)$")
E("G11_TB_17_1_8_4", KB + "t = log_y x: t − 1/t = 8/3 ⇒ t = 3 или −1/3 ⇒ (8; 2), (1/4; 64) (ответ учебника); пара (2; 8) не решение: log₈2 − log₂8 = −8/3",
  k=r"$(8; 2)$, $\left(\dfrac{1}{4}; 64\right)$")
E("G11_TB_17_1_5_4", QG + "под первым логарифмом 2(4·3^x − 6) (§ 17, упр. 5 (4), ответ учебника log₃4); ключ пересчитан: 4t − 6 = t² − 6 при t = 3^x ⇒ t = 4",
  q=r"Решите уравнение: $\log_{2}\left(2(4 \cdot 3^{x} - 6)\right) - \log_{2}(9^{x} - 6) = 1$", k=r"$x = \log_{3} 4$")
E("G11_TB_21_1_1_3", KB + "всего выборов 12·(11·9) + 9·(12·8) = 1188 + 864 = 2052 (ответ учебника); у Нади больше возможностей, если Петя взял яблоко (99 против 96); в ключе было 99 + 96 = 195",
  k=r"$2052$; у Нади больше возможностей, если Петя выбрал яблоко ($99$ против $96$)")
E("G11_TB_21_1_3_24*_2", KB + "A_{x+1}^{n+1}·P_{x−n}/P_{x−1} = (x + 1)!/(x − 1)! = x(x + 1) = 90 ⇒ x = 9 при любом допустимом n — значение n из уравнения не определяется (ключ «n = 4» произволен); вариант «x = 9, n = 5» тоже был верным — закрыт",
  q=r"Решите уравнение: $\dfrac{A_{x+1}^{n+1} \cdot P_{x-n}}{P_{x-1}} = 90$", k=r"$x = 9$ (при любом целом $n$, $0 \le n \le 9$)", drop=[1])
E("G11_TB_21_1_3_24*_3", KB + "A_x^n·P_{x−n} = x!, поэтому уравнение равносильно (x + 2)(x + 1) = 132 ⇒ x = 10 при любом допустимом n (ключ «n = 2» произволен); вариант «x = 10, n = 3» тоже был верным — закрыт; в условии был лишний номер «3:»",
  q=r"Решите уравнение: $\dfrac{P_{x+2}}{A_{x}^{n} \cdot P_{x-n}} = 132$", k=r"$x = 10$ (при любом целом $n$, $0 \le n \le 10$)", drop=[1])
E("G11_TB_21_2_6_1", KB + "T₃ = C_n^2·a^{2(n−2)/3}·a^{−2}: 2(n − 2)/3 = 2 ⇒ n = 5 (было 8)", k=r"$5$", dadd=OLD(r"$8$", "ошибка в показателе"))
E("G11_TB_21_2_5_5", QG + "бином (1/∛a² + ∜a³)^{17} (§ 21, упр. 5 (5)); член без a существует: −2(17 − k)/3 + 3k/4 = 0 ⇒ k = 8, T₉ = C₁₇⁸ = 24310 (было «не существует» для искажённых корней); вариант «C(17, 8)» совпадал с ответом — закрыт",
  q=r"Найдите член разложения $\left( \dfrac{1}{\sqrt[3]{a^{2}}} + \sqrt[4]{a^{3}} \right)^{17}$, не содержащий $a$.", k=r"$T_{9} = C_{17}^{8} = 24310$",
  drop=[0], dadd=OLD(r"не существует", "для искажённого условия"))
E("G11_TB_22_2_24", QG + "«две мужчины и женщины» — ошибка согласования; условие: двое мужчин и женщина", q="На скамейку случайным образом садятся двое мужчин и женщина. Какова вероятность того, что мужчины окажутся рядом?")
E("G11_TB_22_6_1", QG + "формулировка «при двух выстрелах попал в цель» неоднозначна; по учебнику (§ 22, п. 22.5, упр. 1, ответ 0,64) имеется в виду попадание при обоих выстрелах — условие уточнено, ключ 0,64; прежний ключ 0,96 (хотя бы одно попадание) оставлен неверным вариантом",
  q=r"Вероятность того, что стрелок при одном выстреле попадет в цель, равна $0{,}8$. Стрелок сделал два выстрела. Найдите вероятность того, что стрелок попал в цель при обоих выстрелах.",
  k=r"$0{,}64$", drop=[0], dadd=[(r"$0{,}96$", "найдена вероятность хотя бы одного попадания")])
